    def __init__(self, length : int):
        if length < 0:
            raise ValueError('Length of recording cannot be below 0.')
        self.__length = length

    @property
    def length(self):
        return self.__length

    @length.setter
    def length(self, new_length : int):
        if new_length < 0:
            raise ValueError('Length of recording cannot be below 0.')
        self.__length = new_length

